//! The audiomon speaker glyph, drawn in code so the tray icon and the exe/installer icon
//! (generated by build.rs) come from one definition and no image files are shipped.
//! Also compiled into build.rs via `#[path]`, so it depends on nothing but std.

/// Grid the glyph is designed on; sizes scale from it.
const GRID: f32 = 32.0;
/// Subsamples per axis for anti-aliased edges.
const SS: u32 = 4;

/// Straight RGBA pixels (`size * size * 4`, top row first) of the glyph in `color` on transparent.
pub fn speaker_rgba(size: u32, [red, green, blue]: [u8; 3]) -> Vec<u8> {
    let scale = GRID / size as f32;
    let mut rgba = vec![0u8; (size * size * 4) as usize];
    for y in 0..size {
        for x in 0..size {
            let mut hits = 0;
            for sy in 0..SS {
                for sx in 0..SS {
                    let gx = (x as f32 + (sx as f32 + 0.5) / SS as f32) * scale;
                    let gy = (y as f32 + (sy as f32 + 0.5) / SS as f32) * scale;
                    hits += inside(gx, gy) as u32;
                }
            }
            if hits > 0 {
                let i = ((y * size + x) * 4) as usize;
                let alpha = (hits * 255 / (SS * SS)) as u8;
                rgba[i..i + 4].copy_from_slice(&[red, green, blue, alpha]);
            }
        }
    }
    rgba
}

/// Whether a point on the 32-unit grid is ink: a speaker box, its cone, and two sound waves.
fn inside(x: f32, y: f32) -> bool {
    let dy = (y - 16.0).abs();
    let body = (3.0..9.0).contains(&x) && dy < 5.0;
    let cone = (9.0..17.0).contains(&x) && dy < 5.0 + (x - 9.0);
    let r = ((x - 12.0).powi(2) + (y - 16.0).powi(2)).sqrt();
    let wave = x > 18.0 && ((r - 10.5).abs() < 1.3 || (r - 15.5).abs() < 1.3) && dy < r * 0.75;
    body || cone || wave
}
